#if UNITY_EDITOR
using System;
using System.Collections;
using System.IO;
using System.Linq;
using System.Security.Cryptography;
using LastRail.Battle;
using Newtonsoft.Json.Linq;
using NUnit.Framework;
namespace LastRail.Tests.EditMode {
 public class BCarriageBuffTests {
  const string Root="D:/Project/LASTRAIL/";const string QA=Root+"QA/CombatBMigration-20261002/BuffConsumer/";
  static string Hash(string json){using var sha=SHA256.Create();return BitConverter.ToString(sha.ComputeHash(System.Text.Encoding.UTF8.GetBytes(json))).Replace("-","").ToLowerInvariant();}
  static BCarriageBuffDefinitions Definitions(){var json=File.ReadAllText(QA+"original-definitions.json");return new BCarriageBuffDefinitions(json,Hash(json));}
  static CombatExactValue Q(long n,long d=1)=>CombatExactValue.From(new JObject{["numerator"]=n.ToString(),["denominator"]=d.ToString()});
  static JObject Numeric(CombatExactValue b=null,int defense=0)=>new JObject{["version"]=CombatNumericDefenseBudget.Version,["base"]=(b??Q(100)).Snapshot(),["effects"]=new JArray(),["defense"]=Q(defense).Snapshot(),["weakening"]=new JArray(),["penetration"]=new JArray(),["reductions"]=new JObject{["equipment"]=new JArray(),["guardStance"]=new JArray(),["independent"]=new JArray()}};
  static JObject Trace(string type="BCB01",int rank=5)=> (JObject)((JArray)JObject.Parse(File.ReadAllText(Root+"QA/CommanderS1-20260922/combat-b-buff-traces-20261002.json"))["traces"]).Single(t=>(string)t["name"]==type+"_R"+rank+"_ACTUAL_DB_CAPTURE_AND_CALCULATION");
  static JObject Departure(string type="BCB01",int rank=5)=> (JObject)Trace(type,rank)["response"]["departure"].DeepClone();
  static JObject Initial(JObject d,string context="LOCAL_CONTEXT")=>new JObject{["contextId"]=context,["mode"]="EXTERIOR",["cars"]=new JArray(((JArray)d["cars"]).Select(c=>new JObject{["slot"]=c["slot"].DeepClone(),["body"]="NORMAL",["actor"]=(string)c["occupant"]["kind"]=="CARGO"?"ABSENT":"UP"}))};
  static BCarriageBuffModel Model(string type="BCB01",int rank=5){var d=Departure(type,rank);return new BCarriageBuffModel(Definitions(),d,Initial(d));}
  static JObject Action(string id="hit",string kind="BASIC",string target="STRUCTURE",bool direct=true,int slot=0,long revision=0,string ability=null,string timing=null)=>new JObject{
   ["eventId"]=id,["expectedRevision"]=revision,["slot"]=slot,["kind"]=kind,["ability"]=ability??(kind=="HEAL"||kind=="SHIELD"?"ACTIVE":new[]{"BASIC","ACTIVE","ULTIMATE","INTERCEPT"}.Contains(kind)?kind:"EXTERNAL"),
   ["timing"]=timing??(kind=="ACTIVE"||kind=="HEAL"||kind=="SHIELD"?"TIME_COOLDOWN":kind=="INTERCEPT"?"INTERCEPTION_PHASE":"NONE"),["target"]=target,["direct"]=direct,["originalEligible"]=true};
  static JObject Transition(string id,string kind,string value,long revision=0,int slot=0){var t=new JObject{["eventId"]=id,["expectedRevision"]=revision,["kind"]=kind,["value"]=value};if(kind!="MODE")t["slot"]=slot;return t;}
  static void Same(JToken a,JToken b)=>Assert.IsTrue(JToken.DeepEquals(a,b),"expected "+a+" actual "+b);
  static IEnumerable Cases(){foreach(var t in (JArray)JObject.Parse(File.ReadAllText(Root+"QA/CommanderS1-20260922/combat-b-buff-traces-20261002.json"))["traces"])if(((string)t["name"]).Contains("ACTUAL_DB_CAPTURE_AND_CALCULATION"))yield return new TestCaseData((string)t["name"]).SetName("OriginalSqliteTrace_"+(string)t["name"]);}
  [TestCaseSource(nameof(Cases))] public void AllOriginalRankTracesMatch(string name){var t=((JArray)JObject.Parse(File.ReadAllText(Root+"QA/CommanderS1-20260922/combat-b-buff-traces-20261002.json"))["traces"]).Single(x=>(string)x["name"]==name);var d=(JObject)t["response"]["departure"];
   var a=(JObject)t["response"]["accepted"];string context=(string)JArray.Parse((string)a["sourceId"])[1];var m=new BCarriageBuffModel(Definitions(),d,Initial(d,context));
   var input=Action("accepted1",(string)a["kind"],(string)a["target"],(string)a["type"]!="BCB02"&&(string)a["type"]!="BCB03",ability:(string)a["ability"],timing:(string)a["timing"]);Same(a,m.Accept(input));var c=new BCarriageBuffCalculator(m);JObject actual;
   switch((string)a["type"]){case "BCB02":actual=new JObject{["timeMs"]=c.Time("accepted1",Q(12000),15000).Snapshot()};break;
    case "BCB03":actual=new JObject{["prepareMs"]=c.Time("accepted1",Q(300),0).Snapshot(),["recoveryMs"]=c.Time("accepted1",Q(500),0).Snapshot()};break;
    case "BCB05":actual=c.SupportSnapshot("accepted1",Q(514*18,100));break;
    case "BCB06":actual=new JObject{["bodyFlat"]=m.Defense(0,"BODY"),["operatorFlat"]=m.Defense(0,"OPERATOR"),["effectiveOperatorDef"]=BCarriageBuffCalculator.DefenseStat("op_eve",Q(100),Percent("op_eve",5000),m.Defense(0,"OPERATOR")).Snapshot()};break;
    default:actual=c.DamageSnapshot("accepted1",Numeric());break;}
   Same(t["response"]["calculated"],actual);Same(m.Snapshot(),BCarriageBuffModel.Restore(m.Snapshot(),Definitions()).Snapshot());
  }
  static JArray Percent(string owner,int bps)=>new JArray(new JObject{["sourceId"]="original:percent",["ownerId"]=owner,["group"]="EQUIPMENT_DEF",["valueBps"]=bps});
  [Test] public void DefinitionsRequireOriginalHashAndDetachedOutputs(){var j=File.ReadAllText(QA+"original-definitions.json");Assert.Throws<ArgumentException>(()=>new BCarriageBuffDefinitions(j,new string('0',64)));var d=Definitions();var old=d.Capture();d.Capture()["definitions"][0]["values"][0]=999;Same(old,d.Capture());var bad=JObject.Parse(j);bad["definitions"][0]["type"]="BCB02";Assert.Throws<ArgumentException>(()=>new BCarriageBuffDefinitions(bad.ToString(),Hash(bad.ToString())));}
  [Test] public void CandidateInputAndAcceptedOutputsAreDetached(){var d=Departure();var i=Initial(d);var m=new BCarriageBuffModel(Definitions(),d,i);var a=Action();var source=m.Accept(a);d["cars"][0]["rank"]=1;i["mode"]="INTERIOR";a["direct"]=false;source["damageBps"]=999;m.Snapshot()["actions"][0]["source"]["rank"]=1;Assert.AreEqual(5000,(long)m.Source("hit")["damageBps"]);}
  [TestCase("slot")][TestCase("instanceId")][TestCase("operatorId")][TestCase("rank")]
  public void InvalidDuplicateCandidateRejected(string field){var d=Departure();var cars=(JArray)d["cars"];var c=(JObject)cars[0].DeepClone();c["slot"]=1;c["instanceId"]="physical2";c["occupant"]["operatorId"]="op_mira";if(field=="slot")c["slot"]=0;if(field=="instanceId")c["instanceId"]=cars[0]["instanceId"].DeepClone();if(field=="operatorId")c["occupant"]["operatorId"]=cars[0]["occupant"]["operatorId"].DeepClone();if(field=="rank")c["rank"]=1;cars.Add(c);Assert.Throws<ArgumentException>(()=>new BCarriageBuffModel(Definitions(),d,Initial(d)));}
  [Test] public void CatalogDuplicatesHaveDistinctPhysicalSlotsAndSharedRankOnly(){var d=Departure();var car=(JObject)d["cars"][0].DeepClone();car["slot"]=1;car["instanceId"]="physical2";car["occupant"]["operatorId"]="op_mira";((JArray)d["cars"]).Add(car);var m=new BCarriageBuffModel(Definitions(),d,Initial(d));Assert.AreEqual(5000,(long)m.Accept(Action("a"))["damageBps"]);Assert.AreEqual(3000,(long)m.Accept(Action("b",slot:1))["damageBps"]);}
  [TestCase("SENTRY")][TestCase("COMMANDER")][TestCase("DERIVED")][TestCase("REPAIR")][TestCase("ITEM")][TestCase("OVERHEAL")][TestCase("EXPIRY_HEAL")][TestCase("RETURN")][TestCase("SUPPORT3")]
  public void ExcludedKindsReceiveNoBonus(string kind){var m=Model("BCB05");var s=m.Accept(Action(kind,kind));Assert.AreEqual(0,(long)s["damageBps"]);Assert.AreEqual(0,(long)s["supportBps"]);}
  [TestCase(false,true)][TestCase(true,false)] public void OriginalDirectEligibilityCannotBeInvented(bool direct,bool eligible){var m=Model("BCB04");var a=Action(direct:direct);a["originalEligible"]=eligible;Assert.AreEqual(0,(long)m.Accept(a)["damageBps"]);}
  [TestCase("STRUCTURE",5500)][TestCase("ATTACHED",3000)][TestCase("CLIMBING",3000)][TestCase("APPROACH",0)][TestCase("ROOFTOP",0)]
  public void OneTargetCategoryAndFrontGroupOnce(string target,int bps){var m=Model("BCB04");m.Accept(Action(target:target));Assert.AreEqual(bps,(long)m.Source("hit")["damageBps"]);Assert.AreEqual(100+bps/100,new BCarriageBuffCalculator(m).Damage("hit",Numeric()).ToVitalsMagnitude());}
  [Test] public void ExactDamageKeepsOriginalGroupsAndFloorsOnceThenActualHp(){var m=Model();m.Accept(Action());var n=Numeric(Q(101,3),1000);((JArray)n["reductions"]["independent"]).Add(new JObject{["groupId"]="original",["valueBps"]=5000});var c=new BCarriageBuffCalculator(m);Same(Q(101,8).Snapshot(),c.Damage("hit",n).Snapshot()["exact"]);var v=new CombatVitals(100,0,true);Assert.AreEqual(12,v.Damage(c.Damage("hit",n).ToVitalsMagnitude(),0,false).HpLoss);Assert.AreEqual(88,v.Hp);}
  [Test] public void SupportUsesUnroundedBudgetAndOriginalHealShieldLifetimeOwners(){var m=Model("BCB05");m.Accept(Action(kind:"HEAL"));var c=new BCarriageBuffCalculator(m);Same(Q(13878,125).Snapshot(),c.Support("hit",Q(514*18,100)).Snapshot());var v=new CombatVitals(514,0,true);v.Damage(200,0,false);Assert.AreEqual(111,v.RestoreHp((int)c.Support("hit",Q(514*18,100)).Floor(),10000));m.Accept(Action("shield","SHIELD"));var key=new CombatShieldSource("op_eve","original_shield",0);v.Shield(key,(int)c.Support("shield",Q(514*18,100)).Floor(),10,0);Assert.AreEqual(111,v.ShieldRemaining(9));Assert.AreEqual(0,v.ShieldRemaining(10));Assert.AreEqual(425,v.Hp);}
  [TestCase("ACTIVE")][TestCase("HEAL")][TestCase("SHIELD")]
  public void NonDamageTimedActiveHasteIsSameGroupAndUncapped(string kind){var m=Model("BCB02");m.Accept(Action(kind:kind,target:"NONE",direct:false));Same(Q(40000,9).Snapshot(),new BCarriageBuffCalculator(m).Time("hit",Q(12000),15000).Snapshot());Assert.AreEqual(0,(long)m.Source("hit")["damageBps"]);}
  [Test] public void UntimedActiveAndUltimateReceiveNoSkillHaste(){foreach(var a in new[]{Action(kind:"ACTIVE",timing:"NONE"),Action(kind:"HEAL",ability:"ULTIMATE",timing:"NONE")}){var m=Model("BCB02");m.Accept(a);Same(Q(12000).Snapshot(),new BCarriageBuffCalculator(m).Time("hit",Q(12000),0).Snapshot());}}
  [Test] public void InterceptionHasSeparateOriginalPhaseAndRequiresEligibility(){var m=Model("BCB03");m.Accept(Action(kind:"INTERCEPT",target:"NONE",direct:false));Same(Q(3000,13).Snapshot(),new BCarriageBuffCalculator(m).Time("hit",Q(300),0).Snapshot());Assert.AreEqual(0,(long)m.Source("hit")["skillHasteBps"]);var a=Action("bad","INTERCEPT","NONE");a["originalEligible"]=false;Assert.Throws<ArgumentException>(()=>m.Accept(a));}
  [Test] public void FrozenAcceptedSourceSurvivesBreakDownInteriorAndRestore(){foreach(string type in new[]{"BCB01","BCB05"}){var m=Model(type);m.Accept(Action(kind:type=="BCB01"?"BASIC":"HEAL"));var before=m.Source("hit");m.Transition(Transition("break","BODY","BROKEN"));m.Transition(Transition("down","ACTOR","DOWN",1));m.Transition(Transition("inside","MODE","INTERIOR",2));var restored=BCarriageBuffModel.Restore(m.Snapshot(),Definitions());Same(before,restored.Source("hit"));Same(before,restored.Accept(Action(kind:type=="BCB01"?"BASIC":"HEAL")));Assert.Throws<ArgumentException>(()=>restored.Accept(Action("new",revision:3)));}}
  [Test] public void BrokenLivingBaselineRecoveryAndExteriorReevaluateOriginalState(){var m=Model();m.Transition(Transition("b","BODY","BROKEN"));Assert.AreEqual(0,(long)m.Accept(Action("broken",revision:1))["damageBps"]);m.Transition(Transition("d","ACTOR","DOWN",1));Assert.Throws<ArgumentException>(()=>m.Accept(Action("down",revision:2)));m.Transition(Transition("up","ACTOR","UP",2));m.Transition(Transition("normal","BODY","NORMAL",3));m.Transition(Transition("in","MODE","INTERIOR",4));Assert.Throws<ArgumentException>(()=>m.Accept(Action("inside",revision:5)));m.Transition(Transition("out","MODE","EXTERIOR",5));Assert.AreEqual(5000,(long)m.Accept(Action("back",revision:6))["damageBps"]);}
  [Test] public void CargoDownAndBrokenDefenseHaveIndependentRecipients(){var d=Departure("BCB06");var cargo=(JObject)d["cars"][0].DeepClone();cargo["slot"]=1;cargo["instanceId"]="cargo1";cargo["occupant"]=new JObject{["kind"]="CARGO"};((JArray)d["cars"]).Add(cargo);var m=new BCarriageBuffModel(Definitions(),d,Initial(d));Assert.AreEqual(100,m.Defense(1,"BODY"));Assert.AreEqual(0,m.Defense(1,"OPERATOR"));Assert.Throws<ArgumentException>(()=>m.Accept(Action(slot:1)));m.Transition(Transition("down","ACTOR","DOWN"));Assert.AreEqual(100,m.Defense(0,"BODY"));Assert.AreEqual(0,m.Defense(0,"OPERATOR"));m.Transition(Transition("broken","BODY","BROKEN",1));Assert.AreEqual(0,m.Defense(0,"BODY"));Assert.AreEqual(100,m.Defense(1,"BODY"));}
  [Test] public void ReplayAndConflictsAreAtomicAndStrict(){var m=Model();var a=Action();var s=m.Accept(a);var before=m.Snapshot();a["target"]=new JArray("STRUCTURE","ENEMY");Assert.Throws<ArgumentException>(()=>m.Accept(a));Same(before,m.Snapshot());var changed=Action(target:"ENEMY");Assert.Throws<ArgumentException>(()=>m.Accept(changed));Assert.Throws<ArgumentException>(()=>m.Transition(Transition("hit","BODY","BROKEN")));Same(before,m.Snapshot());m.Transition(Transition("b","BODY","BROKEN"));Same(s,m.Accept(Action()));m.Transition(Transition("b","BODY","BROKEN"));Assert.AreEqual(1,m.Revision);}
  [Test] public void StaleMalformedAndInvalidStateNeverPublish(){var m=Model();var before=m.Snapshot();foreach(var a in new[]{Action(revision:1),Action(kind:"BASIC",target:"NONE"),Action(kind:"BASIC",ability:"ACTIVE"),Action(timing:"TIME_COOLDOWN")})Assert.Throws<ArgumentException>(()=>m.Accept(a));Assert.Throws<ArgumentException>(()=>m.Transition(Transition("absent","ACTOR","ABSENT")));Same(before,m.Snapshot());}
  [Test] public void SharedJournalFullReplayRestoreAndOverflowPreserveState(){var m=Model();for(int n=0;n<512;n++){m.Accept(Action("a"+n,revision:n));m.Transition(Transition("t"+n,"BODY",n%2==0?"BROKEN":"NORMAL",n));}Assert.AreEqual(0,(int)m.Capacity()["remaining"]);var before=m.Snapshot();Assert.Throws<ArgumentException>(()=>m.Accept(Action("overflow",revision:512)));Assert.Throws<ArgumentException>(()=>m.Transition(Transition("overflow-t","BODY","BROKEN",512)));Same(before,m.Snapshot());Same(m.Source("a0"),m.Accept(Action("a0")));var restored=BCarriageBuffModel.Restore(before,Definitions());Assert.Throws<ArgumentException>(()=>restored.Accept(Action("overflow",revision:512)));Same(before,restored.Snapshot());((JArray)before["journal"]).Add(before["journal"][0].DeepClone());Assert.Throws<ArgumentException>(()=>BCarriageBuffModel.Restore(before,Definitions()));}
  [TestCase("source")][TestCase("journal")][TestCase("version")][TestCase("departure")]
  public void TamperedSnapshotRejected(string part){var m=Model();m.Accept(Action());var cache=m.Snapshot();if(part=="source")cache["actions"][0]["source"]["damageBps"]=999;if(part=="journal")((JArray)cache["journal"]).Add(cache["journal"][0].DeepClone());if(part=="version")cache["version"]="old";if(part=="departure")cache["departure"]["cars"][0]["rank"]=1;Assert.Throws<ArgumentException>(()=>BCarriageBuffModel.Restore(cache,Definitions()));}
  [TestCase("ACTIVE")][TestCase("HEAL")][TestCase("SHIELD")]
  public void AcceptedTimedActiveDelegatesFinalTickCeilToExistingTimingOwner(string kind){var m=Model("BCB02");m.Accept(Action(kind:kind,target:"NONE",direct:false));var c=new BCarriageBuffCalculator(m);Assert.AreEqual(4445,c.ActiveCooldownTicks("hit",12000000,1000,new[]{new CombatTimingSource("originalH",15000)},Array.Empty<CombatTimingSource>(),null));Assert.AreEqual(3556,c.ActiveCooldownTicks("hit",12000000,1000,new[]{new CombatTimingSource("originalH",15000)},new[]{new CombatTimingSource("originalCDR",2000)},null));}
  [Test] public void BodyDefenseIsCapturedBeforeBreakingHitAndStopsForNewEvents(){var s=Session();var first=s.ApplyIncomingDamage("first","LOCAL_PHYSICAL_1",Numeric(Q(100)),Q(0),new JArray(),0);Assert.AreEqual(90,first.HpLoss);Assert.AreEqual(10,s.Hp("LOCAL_PHYSICAL_1"));Assert.AreEqual(100,BCarriageBuffModel.Restore(s.BuffSnapshot(),Definitions()).Defense(0,"BODY"));var breaking=s.ApplyIncomingDamage("break","LOCAL_PHYSICAL_1",Numeric(Q(11)),Q(0),new JArray(),1);Assert.AreEqual(10,breaking.HpLoss);Assert.AreEqual(3,breaking.TrainHpLoss);Assert.AreEqual(0,BCarriageBuffModel.Restore(s.BuffSnapshot(),Definitions()).Defense(0,"BODY"));}
  [Test] public void AcceptedSupportKeepsNativeExpiryWithoutHealingOrResetFromStateChanges(){var m=Model("BCB05");m.Accept(Action("shield","SHIELD"));var c=new BCarriageBuffCalculator(m);var v=new CombatVitals(514,0,true);v.Damage(200,0,false);v.Shield(new CombatShieldSource("op_eve","original",0),(int)c.Support("shield",Q(514*18,100)).Floor(),10,0);m.Transition(Transition("b","BODY","BROKEN"));m.Transition(Transition("d","ACTOR","DOWN",1));m.Transition(Transition("in","MODE","INTERIOR",2));m.Transition(Transition("up","ACTOR","UP",3));m.Transition(Transition("out","MODE","EXTERIOR",4));Assert.AreEqual(314,v.Hp);Assert.AreEqual(111,v.ShieldRemaining(9));Assert.AreEqual(0,v.ShieldRemaining(10));Assert.AreEqual(111,(int)c.Support("shield",Q(514*18,100)).Floor());}
  [TestCase(0)][TestCase(1)][TestCase(2)][TestCase(3)][TestCase(4)][TestCase(5)]
  public void OriginalOpaqueSourceIdentityPreservesActualServerUtf16Bytes(int index){var t=JObject.Parse(File.ReadAllText(QA+"original-source-identities.json"))["cases"][index];t["initial"]["contextId"]=new string(((JArray)t["contextUnits"]).Select(x=>(char)(int)x).ToArray());t["action"]["eventId"]=new string(((JArray)t["eventUnits"]).Select(x=>(char)(int)x).ToArray());var m=new BCarriageBuffModel(Definitions(),(JObject)t["departure"],(JObject)t["initial"]);Assert.AreEqual((string)t["source"]["sourceId"],(string)m.Accept((JObject)t["action"])["sourceId"]);Same(m.Snapshot(),BCarriageBuffModel.Restore(m.Snapshot(),Definitions()).Snapshot());}
  [Test] public void ActualOwnedEveGrownStatFlowsThroughBuffNumericShieldAndNativeHp(){var profile=JObject.Parse(File.ReadAllText(Root+"QA/CommanderS1-20260922/c3-owned-profile-observed-sql-test-20261001.json"))["profile"];var op=((JArray)profile["operators"]).Single(x=>(string)x["operatorId"]=="op_eve");var grown=CombatExactValue.From((JObject)op["permanentStats"]["attack"]);var atk=CombatStatResolver.Attack("op_eve",grown,new JArray());var m=Model("BCB01",1);m.Accept(Action());var result=new BCarriageBuffCalculator(m).Damage("hit",Numeric(atk,500));Same(Q(25207,750).Snapshot(),result.Snapshot()["exact"]);var enemy=new CombatVitals(700,0,true);enemy.Shield(new CombatShieldSource("enemy","original",0),10,10,0);var hit=enemy.Damage(result.ToVitalsMagnitude(),0,false);Assert.AreEqual(10,hit.Absorbed);Assert.AreEqual(23,hit.HpLoss);Assert.AreEqual(677,enemy.Hp);}
  [Test] public void ActualServerAcceptedBreakSnapshotRestoresWithoutReissuingEffect(){var t=((JArray)JObject.Parse(File.ReadAllText(Root+"QA/CommanderS1-20260922/combat-b-buff-traces-20261002.json"))["traces"]).Single(x=>(string)x["name"]=="ACCEPTED_SOURCE_BREAK_RESTORE_PRESERVED");var m=BCarriageBuffModel.Restore((JObject)t["response"]["snapshot"],Definitions());var c=new BCarriageBuffCalculator(m);Same(t["response"]["after"],c.DamageSnapshot("accepted1",Numeric()));m.Accept(Action("after-break",revision:1));Assert.AreEqual(100,c.Damage("after-break",Numeric()).ToVitalsMagnitude());}
  [Test] public void LocalCoordinatorRejectsNewActionsAfterTrainDefeatButRetainsOriginalSources(){var d=Departure();var bindings=new[]{new BCombatHpBinding("train",1),new BCombatHpBinding("LOCAL_PHYSICAL_1",100),new BCombatHpBinding("op_eve",514)};var s=new BCarriageBuffLocalValidation(Definitions(),d,Initial(d),Formation(),bindings,10000);var original=s.AcceptOriginal(Action("old"));s.ApplyIncomingDamage("end","LOCAL_PHYSICAL_1",Numeric(Q(1000)),Q(0),new JArray(),0);Assert.AreEqual(0,s.Hp("train"));var before=s.Capture();Same(original,s.AcceptOriginal(Action("old")));Assert.Throws<ArgumentException>(()=>s.AcceptOriginal(Action("new",revision:1)));Same(before,s.Capture());}
  static BCombatFormation Formation()=>new BCombatFormation("train",BCombatMode.Solo,BCombatBattlefield.ExternalVertical,new[]{new BCombatSlot("LOCAL_PHYSICAL_1","op_eve")});
  static BCombatHpBinding[] Bindings()=>new[]{new BCombatHpBinding("train",5000),new BCombatHpBinding("LOCAL_PHYSICAL_1",100),new BCombatHpBinding("op_eve",514)};
  static BCarriageBuffLocalValidation Session(string type="BCB06"){var d=Departure(type);return new BCarriageBuffLocalValidation(Definitions(),d,Initial(d),Formation(),Bindings(),10000);}
  [Test] public void BreakingHitUsesCapturedDefenseAndExistingActualLossTransfer(){var s=Session();var r=s.ApplyIncomingDamage("break","LOCAL_PHYSICAL_1",Numeric(Q(1000)),Q(0),new JArray(),0);Assert.AreEqual(100,r.HpLoss);Assert.AreEqual(30,r.TrainHpLoss);Assert.AreEqual(4970,s.Hp("train"));Assert.AreEqual(514,s.Hp("op_eve"));var m=BCarriageBuffModel.Restore(s.BuffSnapshot(),Definitions());Assert.AreEqual(0,m.Defense(0,"BODY"));Same(s.Capture(),BCarriageBuffLocalValidation.Restore(s.Capture(),Definitions(),Formation(),Bindings(),10000).Capture());Assert.AreSame(r,s.ApplyIncomingDamage("break","LOCAL_PHYSICAL_1",Numeric(Q(1000)),Q(0),new JArray(),0));}
  [Test] public void DownHitKeepsNormalBodyDefenseAndExactPercentOrder(){var s=Session();var r=s.ApplyIncomingDamage("down","op_eve",Numeric(Q(1000)),Q(100),Percent("op_eve",5000),0);Assert.AreEqual(514,r.HpLoss);Assert.AreEqual(0,r.TrainHpLoss);var m=BCarriageBuffModel.Restore(s.BuffSnapshot(),Definitions());Assert.AreEqual(100,m.Defense(0,"BODY"));Assert.AreEqual(0,m.Defense(0,"OPERATOR"));}
  [Test] public void FullBuffJournalRejectsBeforePublishingParentHpOrShield(){var s=Session("BCB05");for(int n=0;n<1024;n++)s.AcceptOriginal(Action("a"+n));var before=s.Capture();Assert.Throws<ArgumentException>(()=>s.ApplyIncomingDamage("break","LOCAL_PHYSICAL_1",Numeric(Q(1000)),Q(0),new JArray(),0));Same(before,s.Capture());Assert.Throws<ArgumentException>(()=>s.ApplyShield(Action("shield","SHIELD"),"op_eve",Q(514*18,100),new CombatShieldSource("op_eve","original",0),10,0));Same(before,s.Capture());s.AcceptOriginal(Action("a0"));Same(before,s.Capture());var restored=BCarriageBuffLocalValidation.Restore(before,Definitions(),Formation(),Bindings(),10000);Assert.AreEqual(100,restored.Hp("LOCAL_PHYSICAL_1"));}
  [Test] public void ShieldSourceExpiryReplacementAndAtomicFailureUseExistingOwner(){var s=Session("BCB05");var key=new CombatShieldSource("op_eve","original_shield",0);var r=s.ApplyShield(Action("shield","SHIELD"),"op_eve",Q(514*18,100),key,10,0);Assert.AreEqual(111,r.ShieldAdded);var before=s.Capture();Assert.Throws<ArgumentException>(()=>s.ApplyShield(Action("bad","SHIELD"),"op_eve",Q(1),key,0,0));Same(before,s.Capture());Assert.AreSame(r,s.ApplyShield(Action("shield","SHIELD"),"op_eve",Q(514*18,100),key,10,0));var hp=s.ApplyIncomingDamage("damage","op_eve",Numeric(Q(120)),Q(0),new JArray(),9);Assert.AreEqual(111,hp.Absorbed);Assert.AreEqual(9,hp.HpLoss);Same(s.Capture(),BCarriageBuffLocalValidation.Restore(s.Capture(),Definitions(),Formation(),Bindings(),10000).Capture());}
 }
